package es.uma.urbanpulse.incident;

import java.util.Locale;
import java.util.concurrent.atomic.AtomicReference;

import org.hibernate.resource.jdbc.spi.StatementInspector;

/** Captures the ordered incident SELECT generated by the real list endpoint in performance tests. */
public final class IncidentSqlCaptureInspector implements StatementInspector {

	private static final AtomicReference<String> LAST_ORDERED_INCIDENT_SELECT = new AtomicReference<>();

	@Override
	public String inspect(String sql) {
		String normalized = sql.toLowerCase(Locale.ROOT);
		if (normalized.contains("from \"incident\"") && normalized.contains("order by")) {
			LAST_ORDERED_INCIDENT_SELECT.set(sql);
		}
		return sql;
	}

	static void clear() {
		LAST_ORDERED_INCIDENT_SELECT.set(null);
	}

	static String lastOrderedIncidentSelect() {
		return LAST_ORDERED_INCIDENT_SELECT.get();
	}
}
